// 60-second vertical cut: plays stretches of the full episode back to back, from an edit list
// generated by tools/glass_short.py (which cuts the matching audio from the full mix).
import React from "react";
import { AbsoluteFill, Sequence } from "remotion";
import { GlassV2 } from "./GlassV2";
import { GFPS, Lang } from "./core";
import EDL_EN from "./edl_en.json";
import EDL_RU from "./edl_ru.json";

const EDL: Record<Lang, number[][]> = { en: EDL_EN, ru: EDL_RU };
const fr = (s: number) => Math.round(s * GFPS);
export const shortDuration = (lang: Lang) => EDL[lang].reduce((n, [a, b]) => n + (fr(b) - fr(a)), 0);

export const GlassShort: React.FC<{ lang?: Lang }> = ({ lang = "en" }) => {
  let dst = 0;
  return (
    <AbsoluteFill style={{ background: "#0E0805" }}>
      {EDL[lang].map(([a, b], i) => {
        const len = fr(b) - fr(a), from = dst; dst += len;
        return (
          <Sequence key={i} from={from} durationInFrames={len} layout="absolute-fill">
            <Sequence from={-fr(a)} layout="absolute-fill"><GlassV2 lang={lang} /></Sequence>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};
